-- ▓▓▓▓▓▓▓▓ 20261012000100_search_and_indexes.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Search and speed: full-text search with prefix matching, and indexes for
-- the queries the app runs most. Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

-- array_to_string isn't immutable, so generated columns need this wrapper.
create or replace function public.immutable_join(arr text[])
returns text language sql immutable parallel safe set search_path = ''
as $$ select coalesce(array_to_string(arr, ' '), '') $$;

-- "voi act" → 'voi':* & 'act':*  (each word matches as a prefix; at most 8 words)
create or replace function public.prefix_tsquery(q text)
returns tsquery language sql immutable parallel safe set search_path = ''
as $$
  select case when count(*) = 0 then null
              else to_tsquery('simple', string_agg(w || ':*', ' & ')) end
  from (
    select w from unnest(regexp_split_to_array(
      lower(regexp_replace(coalesce(q, ''), '[^[:alnum:][:space:]]', ' ', 'g')), '\s+')) as w
    where w <> '' limit 8
  ) words
$$;

alter table public.listings add column if not exists search_vector tsvector generated always as (
  setweight(to_tsvector('simple', coalesce(title, '')), 'A') ||
  setweight(to_tsvector('simple', coalesce(summary, '') || ' ' || coalesce(seller_name, '') || ' '
    || coalesce(category, '') || ' ' || public.immutable_join(categories)), 'B') ||
  setweight(to_tsvector('simple', coalesce(description, '')), 'C')) stored;

alter table public.profiles add column if not exists search_vector tsvector generated always as (
  setweight(to_tsvector('simple', coalesce(full_name, '')), 'A') ||
  setweight(to_tsvector('simple', coalesce(bio, '') || ' ' || coalesce(location, '')), 'B')) stored;

alter table public.posts add column if not exists search_vector tsvector generated always as (
  setweight(to_tsvector('simple', coalesce(title, '')), 'A') ||
  setweight(to_tsvector('simple', coalesce(body, '')), 'B')) stored;

create index if not exists listings_search_idx on public.listings using gin (search_vector);
create index if not exists profiles_search_idx on public.profiles using gin (search_vector);
create index if not exists posts_search_idx on public.posts using gin (search_vector);

-- Ranked search. These run with the caller's permissions, so row-level security still applies.
create or replace function public.search_listings(q text)
returns setof public.listings language sql stable set search_path = ''
as $$
  select l.* from public.listings l
  where l.status = 'published' and l.search_vector @@ public.prefix_tsquery(q)
  order by ts_rank(l.search_vector, public.prefix_tsquery(q)) desc, l.created_at desc
$$;

create or replace function public.search_profiles(q text)
returns setof public.profiles language sql stable set search_path = ''
as $$
  select p.* from public.profiles p
  where p.discoverable and p.id is distinct from auth.uid()
    and p.search_vector @@ public.prefix_tsquery(q)
  order by ts_rank(p.search_vector, public.prefix_tsquery(q)) desc, p.created_at desc
$$;

create or replace function public.search_posts(q text)
returns setof public.posts language sql stable set search_path = ''
as $$
  select p.* from public.posts p
  where p.status = 'published' and p.search_vector @@ public.prefix_tsquery(q)
  order by ts_rank(p.search_vector, public.prefix_tsquery(q)) desc, p.published_at desc
$$;

grant execute on function public.search_listings(text), public.search_profiles(text), public.search_posts(text)
  to anon, authenticated;

-- Indexes for common lookups.
create index if not exists listings_categories_idx on public.listings using gin (categories);
create index if not exists listings_project_idx on public.listings (project_id) where project_id is not null;
create index if not exists follows_follower_idx on public.follows (follower_id);
create index if not exists blocks_blocked_idx on public.blocks (blocked_id);
create index if not exists posts_owner_status_idx on public.posts (owner_id, status, published_at desc);
create index if not exists notifications_unread_idx on public.notifications (user_id) where read_at is null;
create index if not exists project_services_status_idx on public.project_services (status, updated_at desc);
create index if not exists offers_listing_status_idx on public.offers (listing_id, status);

-- ▓▓▓▓▓▓▓▓ 20261012000200_characters.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Characters as full records: style guide, asset library, version history,
-- and listings that stay in sync with the character. Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

-- Who may see / change a project. (Teams extend these in a later migration.)
create or replace function public.can_view_project(pid uuid)
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.projects p where p.id = pid and p.owner_id = auth.uid()) $$;

create or replace function public.can_edit_project(pid uuid)
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.projects p where p.id = pid and p.owner_id = auth.uid()) $$;

grant execute on function public.can_view_project(uuid), public.can_edit_project(uuid) to authenticated;

-- Style guide: colors, voice notes, catchphrases, do's and don'ts.
alter table public.projects add column if not exists style_guide jsonb not null default '{}';
alter table public.projects add column if not exists updated_at timestamptz not null default now();
alter table public.projects drop constraint if exists projects_style_guide_size;
alter table public.projects add constraint projects_style_guide_size check (pg_column_size(style_guide) <= 20000);
grant update (style_guide) on public.projects to authenticated;

-- ── Asset library ──
create table if not exists public.character_assets (
  id         uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects (id) on delete cascade,
  added_by   uuid not null default auth.uid() references auth.users (id) on delete cascade,
  kind       text not null default 'reference' check (kind in ('reference', 'turnaround', 'expression', 'logo', 'other')),
  label      text check (label is null or char_length(label) <= 80),
  url        text not null check (url like '%/storage/v1/object/public/character-images/%'),
  created_at timestamptz not null default now()
);
create index if not exists character_assets_project_idx on public.character_assets (project_id, created_at desc);
alter table public.character_assets enable row level security;
drop policy if exists "Assets: view" on public.character_assets;
create policy "Assets: view" on public.character_assets for select to authenticated using (public.can_view_project(project_id));
drop policy if exists "Assets: add" on public.character_assets;
create policy "Assets: add" on public.character_assets for insert to authenticated
  with check (added_by = (select auth.uid()) and public.can_edit_project(project_id));
drop policy if exists "Assets: edit" on public.character_assets;
create policy "Assets: edit" on public.character_assets for update to authenticated
  using (public.can_edit_project(project_id)) with check (public.can_edit_project(project_id));
drop policy if exists "Assets: remove" on public.character_assets;
create policy "Assets: remove" on public.character_assets for delete to authenticated using (public.can_edit_project(project_id));

-- ── Version history: a snapshot of the character before each change ──
create table if not exists public.character_versions (
  id         uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects (id) on delete cascade,
  snapshot   jsonb not null,
  changed_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists character_versions_project_idx on public.character_versions (project_id, created_at desc);
alter table public.character_versions enable row level security;
drop policy if exists "Versions: view" on public.character_versions;
create policy "Versions: view" on public.character_versions for select to authenticated using (public.can_view_project(project_id));
revoke insert, update, delete on public.character_versions from anon, authenticated;

create or replace function public.track_character_change()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  if new.type <> 'original' then return new; end if;
  if (new.name, new.kind, new.color, new.personality, new.description, new.image_url, new.style_guide)
     is not distinct from (old.name, old.kind, old.color, old.personality, old.description, old.image_url, old.style_guide) then
    return new;
  end if;
  new.updated_at := now();
  insert into public.character_versions (project_id, snapshot, changed_by)
  values (old.id, jsonb_build_object(
    'name', old.name, 'kind', old.kind, 'color', old.color, 'personality', old.personality,
    'description', old.description, 'image_url', old.image_url, 'style_guide', old.style_guide,
    'details', old.details, 'saved_at', old.updated_at), auth.uid());
  return new;
end;
$$;
drop trigger if exists track_character_change on public.projects;
create trigger track_character_change before update on public.projects
  for each row execute procedure public.track_character_change();

-- Restore an earlier version (the restore itself is saved as a new version).
create or replace function public.restore_character_version(version uuid)
returns void language plpgsql security definer set search_path = ''
as $$
declare v record;
begin
  select * into v from public.character_versions where id = version;
  if v.id is null or not public.can_edit_project(v.project_id) then raise exception 'Version not found'; end if;
  update public.projects set
    name = v.snapshot ->> 'name', kind = v.snapshot ->> 'kind', color = v.snapshot ->> 'color',
    personality = v.snapshot ->> 'personality', description = v.snapshot ->> 'description',
    image_url = v.snapshot ->> 'image_url', style_guide = coalesce(v.snapshot -> 'style_guide', '{}')
  where id = v.project_id;
end;
$$;
revoke all on function public.restore_character_version(uuid) from public, anon;
grant execute on function public.restore_character_version(uuid) to authenticated;

-- ── Listings follow the character: when the character changes, its listings update too ──
create or replace function public.sync_character_listings()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  if new.type = 'original' and (new.name, new.kind, new.color, new.personality, new.image_url)
     is distinct from (old.name, old.kind, old.color, old.personality, old.image_url) then
    update public.listings set character_info = jsonb_strip_nulls(jsonb_build_object(
      'name', new.name, 'kind', new.kind, 'color', new.color, 'personality', new.personality, 'image_url', new.image_url))
    where project_id = new.id;
  end if;
  return new;
end;
$$;
drop trigger if exists sync_character_listings on public.projects;
create trigger sync_character_listings after update on public.projects
  for each row execute procedure public.sync_character_listings();

-- ▓▓▓▓▓▓▓▓ 20261012000300_workspaces.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Teams: workspaces whose members share characters. Roles: owner, editor, viewer.
-- Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

create table if not exists public.workspaces (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (char_length(btrim(name)) between 1 and 60),
  created_by uuid not null default auth.uid() references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);

create table if not exists public.workspace_members (
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  user_id      uuid not null references auth.users (id) on delete cascade,
  role         text not null default 'editor' check (role in ('owner', 'editor', 'viewer')),
  created_at   timestamptz not null default now(),
  primary key (workspace_id, user_id)
);
create index if not exists workspace_members_user_idx on public.workspace_members (user_id);

create table if not exists public.workspace_invites (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  token        text not null unique default replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
  role         text not null default 'editor' check (role in ('editor', 'viewer')),
  email        text check (email is null or (char_length(email) <= 120 and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$')),
  created_by   uuid not null default auth.uid() references auth.users (id) on delete cascade,
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null default now() + interval '14 days',
  accepted_by  uuid references auth.users (id) on delete set null,
  accepted_at  timestamptz
);
create index if not exists workspace_invites_ws_idx on public.workspace_invites (workspace_id, created_at desc);

-- The signed-in person's role in a workspace, or null.
create or replace function public.workspace_role(ws uuid)
returns text language sql stable security definer set search_path = ''
as $$ select role from public.workspace_members where workspace_id = ws and user_id = auth.uid() $$;
grant execute on function public.workspace_role(uuid) to authenticated;

alter table public.workspaces enable row level security;
alter table public.workspace_members enable row level security;
alter table public.workspace_invites enable row level security;

drop policy if exists "Workspaces: members read" on public.workspaces;
create policy "Workspaces: members read" on public.workspaces for select to authenticated
  using (public.workspace_role(id) is not null);
drop policy if exists "Workspaces: create" on public.workspaces;
create policy "Workspaces: create" on public.workspaces for insert to authenticated
  with check (created_by = (select auth.uid()));
drop policy if exists "Workspaces: owners rename" on public.workspaces;
create policy "Workspaces: owners rename" on public.workspaces for update to authenticated
  using (public.workspace_role(id) = 'owner') with check (public.workspace_role(id) = 'owner');
drop policy if exists "Workspaces: owners delete" on public.workspaces;
create policy "Workspaces: owners delete" on public.workspaces for delete to authenticated
  using (public.workspace_role(id) = 'owner');
revoke update on public.workspaces from anon, authenticated;
grant update (name) on public.workspaces to authenticated;

-- The creator becomes the first owner.
create or replace function public.add_workspace_owner()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  insert into public.workspace_members (workspace_id, user_id, role) values (new.id, new.created_by, 'owner')
  on conflict do nothing;
  return new;
end;
$$;
drop trigger if exists add_workspace_owner on public.workspaces;
create trigger add_workspace_owner after insert on public.workspaces
  for each row execute procedure public.add_workspace_owner();

drop policy if exists "Members: teammates read" on public.workspace_members;
create policy "Members: teammates read" on public.workspace_members for select to authenticated
  using (public.workspace_role(workspace_id) is not null);
drop policy if exists "Members: owners change roles" on public.workspace_members;
create policy "Members: owners change roles" on public.workspace_members for update to authenticated
  using (public.workspace_role(workspace_id) = 'owner' and user_id <> (select auth.uid()))
  with check (public.workspace_role(workspace_id) = 'owner');
drop policy if exists "Members: owners remove, anyone leaves" on public.workspace_members;
create policy "Members: owners remove, anyone leaves" on public.workspace_members for delete to authenticated
  using (user_id = (select auth.uid()) or public.workspace_role(workspace_id) = 'owner');
revoke insert on public.workspace_members from anon, authenticated;
revoke update on public.workspace_members from anon, authenticated;
grant update (role) on public.workspace_members to authenticated;

-- A workspace always keeps at least one owner.
create or replace function public.keep_an_owner()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare ws uuid := coalesce(old.workspace_id, new.workspace_id);
begin
  if exists (select 1 from public.workspaces w where w.id = ws)
     and not exists (select 1 from public.workspace_members m where m.workspace_id = ws and m.role = 'owner') then
    raise exception 'A workspace needs at least one owner';
  end if;
  return null;
end;
$$;
drop trigger if exists keep_an_owner on public.workspace_members;
create trigger keep_an_owner after update or delete on public.workspace_members
  for each row execute procedure public.keep_an_owner();

drop policy if exists "Invites: owners manage" on public.workspace_invites;
create policy "Invites: owners manage" on public.workspace_invites for all to authenticated
  using (public.workspace_role(workspace_id) = 'owner')
  with check (public.workspace_role(workspace_id) = 'owner' and created_by = (select auth.uid()));

-- What an invite link is for, before accepting it.
create or replace function public.invite_preview(invite_token text)
returns table (workspace_name text, role text, invited_by text, expired boolean, used boolean)
language sql stable security definer set search_path = ''
as $$
  select w.name, i.role, coalesce(p.full_name, 'A tsayvish member'), i.expires_at < now(), i.accepted_at is not null
  from public.workspace_invites i
  join public.workspaces w on w.id = i.workspace_id
  left join public.profiles p on p.id = i.created_by
  where i.token = invite_token
$$;
revoke all on function public.invite_preview(text) from public, anon;
grant execute on function public.invite_preview(text) to authenticated;

create or replace function public.accept_workspace_invite(invite_token text)
returns uuid language plpgsql security definer set search_path = ''
as $$
declare i record;
begin
  select * into i from public.workspace_invites where token = invite_token for update;
  if i.id is null then raise exception 'This invite link isn’t valid'; end if;
  if i.accepted_at is not null then raise exception 'This invite has already been used'; end if;
  if i.expires_at < now() then raise exception 'This invite has expired. Ask for a new link.'; end if;
  if i.email is not null and lower(i.email) <> lower(coalesce(auth.email(), '')) then
    raise exception 'This invite was sent to a different email address';
  end if;
  insert into public.workspace_members (workspace_id, user_id, role) values (i.workspace_id, auth.uid(), i.role)
  on conflict (workspace_id, user_id) do nothing;
  update public.workspace_invites set accepted_by = auth.uid(), accepted_at = now() where id = i.id;
  return i.workspace_id;
end;
$$;
revoke all on function public.accept_workspace_invite(text) from public, anon;
grant execute on function public.accept_workspace_invite(text) to authenticated;

-- ── Characters (projects) can belong to a workspace ──
alter table public.projects add column if not exists workspace_id uuid references public.workspaces (id) on delete set null;
create index if not exists projects_workspace_idx on public.projects (workspace_id, created_at desc) where workspace_id is not null;
grant update (workspace_id) on public.projects to authenticated;

create or replace function public.can_view_project(pid uuid)
returns boolean language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.projects p where p.id = pid and (
    p.owner_id = auth.uid()
    or (p.workspace_id is not null and public.workspace_role(p.workspace_id) is not null)))
$$;

create or replace function public.can_edit_project(pid uuid)
returns boolean language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.projects p where p.id = pid and (
    p.owner_id = auth.uid()
    or (p.workspace_id is not null and public.workspace_role(p.workspace_id) in ('owner', 'editor'))))
$$;

drop policy if exists "Projects: read own" on public.projects;
drop policy if exists "Projects: read own or team" on public.projects;
create policy "Projects: read own or team" on public.projects for select using (
  (select auth.uid()) = owner_id
  or (workspace_id is not null and public.workspace_role(workspace_id) is not null));

drop policy if exists "Projects: create own" on public.projects;
create policy "Projects: create own" on public.projects for insert with check (
  (select auth.uid()) = owner_id
  and ((type = 'original' and status is null) or (type = 'partnership' and status = 'submitted'))
  and (workspace_id is null or public.workspace_role(workspace_id) in ('owner', 'editor')));

drop policy if exists "Projects: update own" on public.projects;
drop policy if exists "Projects: update own or team" on public.projects;
create policy "Projects: update own or team" on public.projects for update
  using ((select auth.uid()) = owner_id
         or (workspace_id is not null and public.workspace_role(workspace_id) in ('owner', 'editor')))
  with check (workspace_id is null or public.workspace_role(workspace_id) in ('owner', 'editor')
              or (select auth.uid()) = owner_id);

drop policy if exists "Projects: delete own" on public.projects;
create policy "Projects: delete own" on public.projects for delete using (
  (select auth.uid()) = owner_id
  or (workspace_id is not null and public.workspace_role(workspace_id) = 'owner'));

-- Only the character's creator can move it into (or out of) a workspace, and only one they can edit.
create or replace function public.guard_project_workspace()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  if new.workspace_id is distinct from old.workspace_id and auth.uid() is not null then
    if auth.uid() <> old.owner_id then raise exception 'Only the person who created this can move it'; end if;
    if new.workspace_id is not null and public.workspace_role(new.workspace_id) not in ('owner', 'editor') then
      raise exception 'You can only move it into a workspace you can edit';
    end if;
  end if;
  return new;
end;
$$;
drop trigger if exists guard_project_workspace on public.projects;
create trigger guard_project_workspace before update on public.projects
  for each row execute procedure public.guard_project_workspace();

-- Services follow the same access as their project.
drop policy if exists "Services: read own" on public.project_services;
create policy "Services: read own" on public.project_services for select using (public.can_view_project(project_id));
drop policy if exists "Services: add own" on public.project_services;
create policy "Services: add own" on public.project_services for insert with check (public.can_edit_project(project_id));
drop policy if exists "Services: update own" on public.project_services;
create policy "Services: update own" on public.project_services for update
  using (public.can_edit_project(project_id)) with check (public.can_edit_project(project_id));

-- Teammates can see each other's profile.
drop policy if exists "Profiles: teammates read" on public.profiles;
create policy "Profiles: teammates read" on public.profiles for select to authenticated using (
  exists (select 1 from public.workspace_members a
          join public.workspace_members b on b.workspace_id = a.workspace_id
          where a.user_id = (select auth.uid()) and b.user_id = profiles.id));

-- ▓▓▓▓▓▓▓▓ 20261012000400_admin.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Admin console: staff, service-request queue, moderation, bans, audit log.
-- Make yourself an admin (once, in the SQL Editor):
--   insert into public.staff (user_id, role)
--   select id, 'admin' from auth.users where email = 'you@example.com'
--   on conflict (user_id) do update set role = 'admin';
-- Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

create table if not exists public.staff (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  role       text not null default 'agent' check (role in ('admin', 'agent')),
  created_at timestamptz not null default now()
);
alter table public.staff enable row level security;
revoke insert, update, delete on public.staff from anon, authenticated;

create or replace function public.is_staff()
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.staff where user_id = auth.uid()) $$;
grant execute on function public.is_staff() to anon, authenticated;

drop policy if exists "Staff: staff read" on public.staff;
create policy "Staff: staff read" on public.staff for select to authenticated using (public.is_staff());

-- ── Bans: a banned member can still log in and read, but can't post, list, offer or message ──
create table if not exists public.bans (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  reason     text check (reason is null or char_length(reason) <= 500),
  banned_by  uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.bans enable row level security;
revoke insert, update, delete on public.bans from anon, authenticated;
drop policy if exists "Bans: staff read" on public.bans;
create policy "Bans: staff read" on public.bans for select to authenticated using (public.is_staff());

create or replace function public.is_banned(uid uuid default auth.uid())
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.bans where user_id = uid) $$;
grant execute on function public.is_banned(uuid) to authenticated;

-- ── Audit log of every staff action ──
create table if not exists public.admin_actions (
  id          uuid primary key default gen_random_uuid(),
  actor_id    uuid references auth.users (id) on delete set null,
  action      text not null,
  target_type text not null,
  target_id   text not null,
  details     jsonb not null default '{}',
  created_at  timestamptz not null default now()
);
create index if not exists admin_actions_created_idx on public.admin_actions (created_at desc);
alter table public.admin_actions enable row level security;
revoke insert, update, delete on public.admin_actions from anon, authenticated;
drop policy if exists "Audit: staff read" on public.admin_actions;
create policy "Audit: staff read" on public.admin_actions for select to authenticated using (public.is_staff());

create or replace function public.log_admin_action(p_action text, p_type text, p_id text, p_details jsonb default '{}')
returns void language sql security definer set search_path = ''
as $$ insert into public.admin_actions (actor_id, action, target_type, target_id, details) values (auth.uid(), p_action, p_type, p_id, p_details) $$;
revoke all on function public.log_admin_action(text, text, text, jsonb) from public, anon, authenticated;

-- ── Service tickets: staff-only working fields for each requested service ──
create table if not exists public.service_tickets (
  project_id    uuid not null references public.projects (id) on delete cascade,
  service       text not null,
  assignee      uuid references auth.users (id) on delete set null,
  due_on        date,
  internal_note text check (internal_note is null or char_length(internal_note) <= 4000),
  updated_at    timestamptz not null default now(),
  primary key (project_id, service)
);
alter table public.service_tickets enable row level security;
revoke insert, update, delete on public.service_tickets from anon, authenticated;
drop policy if exists "Tickets: staff read" on public.service_tickets;
create policy "Tickets: staff read" on public.service_tickets for select to authenticated using (public.is_staff());

-- ── Updates the creator can see on a service tab ──
create table if not exists public.service_updates (
  id         uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects (id) on delete cascade,
  service    text not null,
  author_id  uuid references auth.users (id) on delete set null,
  body       text not null check (char_length(btrim(body)) between 1 and 4000),
  created_at timestamptz not null default now()
);
create index if not exists service_updates_project_idx on public.service_updates (project_id, service, created_at desc);
alter table public.service_updates enable row level security;
revoke insert, update, delete on public.service_updates from anon, authenticated;
drop policy if exists "Service updates: project members read" on public.service_updates;
create policy "Service updates: project members read" on public.service_updates for select to authenticated
  using (public.can_view_project(project_id) or public.is_staff());

-- ── Notifications: more kinds, and a link to a project ──
alter table public.notifications add column if not exists project_id uuid references public.projects (id) on delete cascade;
alter table public.notifications add column if not exists body text check (body is null or char_length(body) <= 300);
alter table public.notifications drop constraint if exists notifications_type_check;
alter table public.notifications add constraint notifications_type_check check (type in (
  'offer_received', 'offer_accepted', 'offer_declined', 'offer_withdrawn', 'offer_paid', 'new_follower',
  'service_update', 'service_active', 'partnership_update', 'agreement_proposed', 'agreement_signed', 'credits_added'));

-- ── Staff can read everything they need to run the platform ──
drop policy if exists "Staff read all" on public.projects;
create policy "Staff read all" on public.projects for select to authenticated using (public.is_staff());
drop policy if exists "Staff read all" on public.project_services;
create policy "Staff read all" on public.project_services for select to authenticated using (public.is_staff());
drop policy if exists "Staff read all" on public.profiles;
create policy "Staff read all" on public.profiles for select to authenticated using (public.is_staff());
drop policy if exists "Staff read all" on public.listings;
create policy "Staff read all" on public.listings for select to authenticated using (public.is_staff());
drop policy if exists "Staff read all" on public.reports;
create policy "Staff read all" on public.reports for select to authenticated using (public.is_staff());
