-- Staff may set a service active (members still can't).
create or replace function public.guard_service_status()
returns trigger language plpgsql set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') in ('authenticated', 'anon') and not public.is_staff() then
    if tg_op = 'INSERT' and new.status = 'active' then
      raise exception 'Only the tsayvish team can mark a service active';
    end if;
    if tg_op = 'UPDATE' and new.status is distinct from old.status
       and (new.status = 'active' or old.status = 'active') then
      raise exception 'Only the tsayvish team can change an active service';
    end if;
  end if;
  new.updated_at = now();
  return new;
end;
$$;

-- ── Staff actions (each one checks staff and writes to the audit log) ──
create or replace function public.require_staff()
returns void language plpgsql stable security definer set search_path = ''
as $$ begin if not public.is_staff() then raise exception 'Staff only'; end if; end; $$;
revoke all on function public.require_staff() from public, anon, authenticated;

create or replace function public.admin_update_service(
  p_project uuid, p_service text, p_status text, p_assignee uuid, p_due date, p_note text)
returns void language plpgsql security definer set search_path = ''
as $$
declare old_status text; owner uuid;
begin
  perform public.require_staff();
  if p_status not in ('off', 'requested', 'active') then raise exception 'Unknown status'; end if;
  select status into old_status from public.project_services where project_id = p_project and service = p_service;
  if old_status is null then raise exception 'Service not found'; end if;
  update public.project_services set status = p_status where project_id = p_project and service = p_service;
  insert into public.service_tickets (project_id, service, assignee, due_on, internal_note, updated_at)
  values (p_project, p_service, p_assignee, p_due, nullif(btrim(coalesce(p_note, '')), ''), now())
  on conflict (project_id, service) do update set assignee = excluded.assignee, due_on = excluded.due_on,
    internal_note = excluded.internal_note, updated_at = now();
  if p_status = 'active' and old_status <> 'active' then
    select owner_id into owner from public.projects where id = p_project;
    insert into public.notifications (user_id, type, actor_id, project_id, body)
    values (owner, 'service_active', auth.uid(), p_project, p_service || ' is now active');
  end if;
  perform public.log_admin_action('update_service', 'project_service', p_project::text || ':' || p_service,
    jsonb_build_object('from', old_status, 'to', p_status, 'assignee', p_assignee, 'due_on', p_due));
end;
$$;

create or replace function public.admin_post_service_update(p_project uuid, p_service text, p_body text)
returns void language plpgsql security definer set search_path = ''
as $$
declare owner uuid;
begin
  perform public.require_staff();
  insert into public.service_updates (project_id, service, author_id, body) values (p_project, p_service, auth.uid(), btrim(p_body));
  select owner_id into owner from public.projects where id = p_project;
  insert into public.notifications (user_id, type, actor_id, project_id, body)
  values (owner, 'service_update', auth.uid(), p_project, left(p_service || ': ' || btrim(p_body), 300));
  perform public.log_admin_action('post_service_update', 'project_service', p_project::text || ':' || p_service, '{}');
end;
$$;

create or replace function public.admin_set_partnership_status(p_project uuid, p_status text, p_message text)
returns void language plpgsql security definer set search_path = ''
as $$
declare owner uuid; old_status text;
begin
  perform public.require_staff();
  if p_status not in ('submitted', 'in_review', 'approved', 'declined') then raise exception 'Unknown status'; end if;
  select owner_id, status into owner, old_status from public.projects where id = p_project and type = 'partnership';
  if owner is null then raise exception 'Partnership not found'; end if;
  update public.projects set status = p_status where id = p_project;
  insert into public.notifications (user_id, type, actor_id, project_id, body)
  values (owner, 'partnership_update', auth.uid(), p_project,
          left(coalesce(nullif(btrim(coalesce(p_message, '')), ''), 'Status changed to ' || replace(p_status, '_', ' ')), 300));
  perform public.log_admin_action('set_partnership_status', 'project', p_project::text, jsonb_build_object('from', old_status, 'to', p_status));
end;
$$;

create or replace function public.admin_set_report(p_report uuid, p_status text)
returns void language plpgsql security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  if p_status not in ('open', 'resolved', 'dismissed') then raise exception 'Unknown status'; end if;
  update public.reports set status = p_status where id = p_report;
  if not found then raise exception 'Report not found'; end if;
  perform public.log_admin_action('set_report', 'report', p_report::text, jsonb_build_object('status', p_status));
end;
$$;

create or replace function public.admin_hide_content(p_type text, p_id uuid)
returns void language plpgsql security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  if p_type = 'listing' then update public.listings set status = 'hidden' where id = p_id;
  elsif p_type = 'post' then update public.posts set status = 'draft' where id = p_id;
  else raise exception 'Can only hide listings and posts'; end if;
  perform public.log_admin_action('hide_content', p_type, p_id::text, '{}');
end;
$$;

create or replace function public.admin_ban(p_user uuid, p_reason text)
returns void language plpgsql security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  if exists (select 1 from public.staff where user_id = p_user) then raise exception 'Staff can’t be banned here'; end if;
  insert into public.bans (user_id, reason, banned_by) values (p_user, nullif(btrim(coalesce(p_reason, '')), ''), auth.uid())
  on conflict (user_id) do update set reason = excluded.reason, banned_by = excluded.banned_by, created_at = now();
  update public.listings set status = 'hidden' where owner_id = p_user;
  update public.profiles set discoverable = false where id = p_user;
  perform public.log_admin_action('ban', 'user', p_user::text, jsonb_build_object('reason', p_reason));
end;
$$;

create or replace function public.admin_unban(p_user uuid)
returns void language plpgsql security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  delete from public.bans where user_id = p_user;
  perform public.log_admin_action('unban', 'user', p_user::text, '{}');
end;
$$;

-- Find members by name or email (staff only).
create or replace function public.admin_find_users(q text)
returns table (id uuid, email text, full_name text, created_at timestamptz, banned boolean, staff_role text)
language plpgsql stable security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  return query
    select u.id, u.email::text, p.full_name, u.created_at,
           exists (select 1 from public.bans b where b.user_id = u.id),
           (select s.role from public.staff s where s.user_id = u.id)
    from auth.users u left join public.profiles p on p.id = u.id
    where coalesce(q, '') = '' or u.email ilike '%' || q || '%' or p.full_name ilike '%' || q || '%'
    order by u.created_at desc limit 100;
end;
$$;

create or replace function public.admin_staff_list()
returns table (user_id uuid, full_name text, email text, role text)
language plpgsql stable security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  return query select s.user_id, p.full_name, u.email::text, s.role
    from public.staff s join auth.users u on u.id = s.user_id left join public.profiles p on p.id = s.user_id
    order by p.full_name nulls last;
end;
$$;

do $$
declare f text;
begin
  foreach f in array array[
    'admin_update_service(uuid, text, text, uuid, date, text)', 'admin_post_service_update(uuid, text, text)',
    'admin_set_partnership_status(uuid, text, text)', 'admin_set_report(uuid, text)', 'admin_hide_content(text, uuid)',
    'admin_ban(uuid, text)', 'admin_unban(uuid)', 'admin_find_users(text)', 'admin_staff_list()'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- ▓▓▓▓▓▓▓▓ 20261012000500_agreements.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- License agreements: an accepted offer gets written terms both sides accept.
-- (Click-to-accept with a typed name. Swap in an e-signature provider later.)
-- Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

create table if not exists public.agreements (
  offer_id           uuid primary key references public.offers (id) on delete cascade,
  terms              jsonb not null default '{}' check (pg_column_size(terms) <= 30000),
  version            integer not null default 1,
  status             text not null default 'proposed' check (status in ('proposed', 'signed')),
  seller_accepted_at timestamptz,
  seller_signature   text check (seller_signature is null or char_length(seller_signature) <= 120),
  buyer_accepted_at  timestamptz,
  buyer_signature    text check (buyer_signature is null or char_length(buyer_signature) <= 120),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
alter table public.agreements enable row level security;
revoke insert, update, delete on public.agreements from anon, authenticated;
drop policy if exists "Agreements: parties read" on public.agreements;
create policy "Agreements: parties read" on public.agreements for select to authenticated using (
  public.is_staff() or exists (select 1 from public.offers o where o.id = offer_id
    and (o.buyer_id = (select auth.uid()) or o.seller_id = (select auth.uid()))));

-- The seller writes (or revises) the terms. Any revision clears both acceptances.
create or replace function public.propose_agreement(p_offer uuid, p_terms jsonb)
returns void language plpgsql security definer set search_path = ''
as $$
declare o record;
begin
  select * into o from public.offers where id = p_offer;
  if o.id is null or o.seller_id <> auth.uid() then raise exception 'Only the seller can write the agreement'; end if;
  if o.status <> 'accepted' then raise exception 'The offer must be accepted first'; end if;
  if exists (select 1 from public.agreements where offer_id = p_offer and status = 'signed') then
    raise exception 'This agreement is already signed';
  end if;
  insert into public.agreements (offer_id, terms) values (p_offer, p_terms)
  on conflict (offer_id) do update set terms = excluded.terms, version = public.agreements.version + 1,
    status = 'proposed', seller_accepted_at = null, seller_signature = null,
    buyer_accepted_at = null, buyer_signature = null, updated_at = now();
  insert into public.notifications (user_id, type, actor_id, offer_id, listing_id)
  values (o.buyer_id, 'agreement_proposed', o.seller_id, o.id, o.listing_id);
end;
$$;

-- Either side accepts by typing their name. When both have, it's signed.
create or replace function public.accept_agreement(p_offer uuid, p_signature text, p_version integer)
returns void language plpgsql security definer set search_path = ''
as $$
declare o record; a record; sig text := btrim(coalesce(p_signature, ''));
begin
  select * into o from public.offers where id = p_offer;
  select * into a from public.agreements where offer_id = p_offer for update;
  if o.id is null or a.offer_id is null then raise exception 'Agreement not found'; end if;
  if auth.uid() not in (o.buyer_id, o.seller_id) then raise exception 'Only the buyer or seller can accept'; end if;
  if a.status = 'signed' then raise exception 'Already signed'; end if;
  if a.version <> p_version then raise exception 'The terms changed. Review the latest version.'; end if;
  if char_length(sig) < 2 then raise exception 'Type your full name to accept'; end if;
  if auth.uid() = o.seller_id then
    update public.agreements set seller_accepted_at = now(), seller_signature = sig, updated_at = now() where offer_id = p_offer;
  else
    update public.agreements set buyer_accepted_at = now(), buyer_signature = sig, updated_at = now() where offer_id = p_offer;
  end if;
  select * into a from public.agreements where offer_id = p_offer;
  if a.seller_accepted_at is not null and a.buyer_accepted_at is not null then
    update public.agreements set status = 'signed', updated_at = now() where offer_id = p_offer;
    insert into public.notifications (user_id, type, actor_id, offer_id, listing_id)
    values (case when auth.uid() = o.seller_id then o.buyer_id else o.seller_id end, 'agreement_signed', auth.uid(), o.id, o.listing_id);
  end if;
end;
$$;

revoke all on function public.propose_agreement(uuid, jsonb), public.accept_agreement(uuid, text, integer) from public, anon;
grant execute on function public.propose_agreement(uuid, jsonb), public.accept_agreement(uuid, text, integer) to authenticated;

-- ▓▓▓▓▓▓▓▓ 20261012000600_safety.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Trust and safety: rate limits, verified email to take part, and bans enforced.
-- Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

create or replace function public.is_verified(uid uuid default auth.uid())
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from auth.users where id = uid and email_confirmed_at is not null) $$;
grant execute on function public.is_verified(uuid) to authenticated;

-- Blocks banned members (and, where asked, unverified ones) from creating things.
-- Usage: before insert ... execute procedure public.member_can_create('verified') — or no argument.
create or replace function public.member_can_create()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  if auth.uid() is null then return new; end if;            -- server/admin writes
  if public.is_banned(auth.uid()) then
    raise exception 'Your account is restricted. Contact support@tsayvish.com if you think this is a mistake.';
  end if;
  if tg_nargs > 0 and tg_argv[0] = 'verified' and not public.is_verified(auth.uid()) then
    raise exception 'Confirm your email address first. Check your inbox for the link.';
  end if;
  return new;
end;
$$;

-- Rate limit: at most tg_argv[2] rows per tg_argv[1] (an interval) for the user in column tg_argv[0].
create or replace function public.rate_limit()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare n integer; col text := tg_argv[0]; win interval := tg_argv[1]::interval; cap integer := tg_argv[2]::integer;
begin
  if auth.uid() is null then return new; end if;
  execute format('select count(*) from %I.%I where %I = $1 and created_at > now() - $2', tg_table_schema, tg_table_name, col)
    into n using auth.uid(), win;
  if n >= cap then
    raise exception 'You’re doing that too often. Please wait a little and try again.' using errcode = 'P0001', hint = 'rate_limited';
  end if;
  return new;
end;
$$;

do $$
declare t record;
begin
  -- table, user column, window, max, needs verified email
  for t in select * from (values
    ('messages',          'sender_id',   '1 minute', 30,   true),
    ('offers',            'buyer_id',    '1 hour',   20,   true),
    ('listings',          'owner_id',    '1 day',    30,   true),
    ('posts',             'owner_id',    '1 day',    30,   true),
    ('reports',           'reporter_id', '1 day',    20,   false),
    ('follows',           'follower_id', '1 hour',   100,  false),
    ('projects',          'owner_id',    '1 day',    300,  false),
    ('workspace_invites', 'created_by',  '1 day',    50,   true),
    ('character_assets',  'added_by',    '1 hour',   200,  false)
  ) as v(tbl, col, win, cap, verified) loop
    execute format('drop trigger if exists rate_limit on public.%I', t.tbl);
    execute format('create trigger rate_limit before insert on public.%I for each row execute procedure public.rate_limit(%L, %L, %L)',
                   t.tbl, t.col, t.win, t.cap);
    execute format('drop trigger if exists member_can_create on public.%I', t.tbl);
    if t.verified then
      execute format('create trigger member_can_create before insert on public.%I for each row execute procedure public.member_can_create(%L)', t.tbl, 'verified');
    else
      execute format('create trigger member_can_create before insert on public.%I for each row execute procedure public.member_can_create()', t.tbl);
    end if;
  end loop;
end $$;

-- A second, daily cap on messages.
drop trigger if exists rate_limit_daily on public.messages;
create trigger rate_limit_daily before insert on public.messages
  for each row execute procedure public.rate_limit('sender_id', '1 day', '1000');

-- Banned members can't start new chats either.
create or replace function public.guard_new_conversation()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  if auth.uid() is not null and public.is_banned(auth.uid()) then raise exception 'Your account is restricted.'; end if;
  return new;
end;
$$;
drop trigger if exists guard_new_conversation on public.conversations;
create trigger guard_new_conversation before insert on public.conversations
  for each row execute procedure public.guard_new_conversation();

-- ▓▓▓▓▓▓▓▓ 20261012000700_public_pages.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Public pages: visitors who aren't signed in can see published listings,
-- discoverable creators and their public posts. Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

drop policy if exists "Listings: public read published" on public.listings;
create policy "Listings: public read published" on public.listings for select to anon using (status = 'published');

drop policy if exists "Profiles: public read discoverable" on public.profiles;
create policy "Profiles: public read discoverable" on public.profiles for select to anon using (discoverable);

drop policy if exists "Posts: public read" on public.posts;
create policy "Posts: public read" on public.posts for select to anon using (status = 'published' and visibility = 'public');

-- Follower counts for public pages (no names).
create or replace function public.follower_count(creator uuid)
returns integer language sql stable security definer set search_path = ''
as $$ select count(*)::int from public.follows where creator_id = creator $$;
grant execute on function public.follower_count(uuid) to anon, authenticated;

-- ▓▓▓▓▓▓▓▓ 20261012000800_insights_onboarding.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Onboarding, listing and profile views, sales insights, and ranked Discover.
-- Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

alter table public.profiles add column if not exists onboarded_at timestamptz;
alter table public.profiles add column if not exists interests text[] not null default '{}';
alter table public.profiles drop constraint if exists profiles_interests_check;
alter table public.profiles add constraint profiles_interests_check check (cardinality(interests) <= 12);
-- People who joined before onboarding existed skip it.
update public.profiles set onboarded_at = created_at where onboarded_at is null and created_at < timestamptz '2026-10-12';

-- ── Views: one per viewer per item per day ──
create table if not exists public.listing_views (
  listing_id uuid not null references public.listings (id) on delete cascade,
  viewer_id  uuid not null references auth.users (id) on delete cascade,
  day        date not null default current_date,
  created_at timestamptz not null default now(),
  primary key (listing_id, viewer_id, day)
);
create index if not exists listing_views_day_idx on public.listing_views (listing_id, day);
create table if not exists public.profile_views (
  profile_id uuid not null references auth.users (id) on delete cascade,
  viewer_id  uuid not null references auth.users (id) on delete cascade,
  day        date not null default current_date,
  created_at timestamptz not null default now(),
  primary key (profile_id, viewer_id, day)
);
alter table public.listing_views enable row level security;
alter table public.profile_views enable row level security;
revoke insert, update, delete on public.listing_views, public.profile_views from anon, authenticated;
drop policy if exists "Listing views: owner reads" on public.listing_views;
create policy "Listing views: owner reads" on public.listing_views for select to authenticated using (
  exists (select 1 from public.listings l where l.id = listing_id and l.owner_id = (select auth.uid())));
drop policy if exists "Profile views: owner reads" on public.profile_views;
create policy "Profile views: owner reads" on public.profile_views for select to authenticated using (profile_id = (select auth.uid()));

create or replace function public.log_view(p_kind text, p_id uuid)
returns void language plpgsql security definer set search_path = ''
as $$
begin
  if auth.uid() is null then return; end if;
  if p_kind = 'listing' then
    insert into public.listing_views (listing_id, viewer_id)
    select p_id, auth.uid() from public.listings where id = p_id and owner_id <> auth.uid() and status = 'published'
    on conflict do nothing;
  elsif p_kind = 'profile' and p_id <> auth.uid() then
    insert into public.profile_views (profile_id, viewer_id) values (p_id, auth.uid()) on conflict do nothing;
  end if;
end;
$$;
revoke all on function public.log_view(text, uuid) from public, anon;
grant execute on function public.log_view(text, uuid) to authenticated;

-- Daily totals for the signed-in creator, for Insights.
create or replace function public.my_daily_stats(since date)
returns table (day date, listing_views integer, profile_views integer, sales numeric, followers integer)
language sql stable security definer set search_path = ''
as $$
  with days as (select generate_series(since, current_date, interval '1 day')::date as day)
  select d.day,
    (select count(*)::int from public.listing_views v join public.listings l on l.id = v.listing_id
       where l.owner_id = auth.uid() and v.day = d.day),
    (select count(*)::int from public.profile_views v where v.profile_id = auth.uid() and v.day = d.day),
    (select coalesce(sum(o.amount), 0) from public.offers o
       where o.seller_id = auth.uid() and o.status = 'accepted' and o.responded_at::date = d.day),
    (select count(*)::int from public.follows f where f.creator_id = auth.uid() and f.created_at::date = d.day)
  from days d order by d.day
$$;
revoke all on function public.my_daily_stats(date) from public, anon;
grant execute on function public.my_daily_stats(date) to authenticated;

-- ── Ranked Discover ──
-- Listings: recent views and offers count, with a boost for new listings and the viewer's interests.
create or replace function public.discover_listings(p_topic text default null, p_limit integer default 16)
returns setof public.listings language sql stable security definer set search_path = ''
as $$
  select l.* from public.listings l
  left join lateral (select count(*) as n from public.listing_views v where v.listing_id = l.id and v.day > current_date - 14) views on true
  left join lateral (select count(*) as n from public.offers o where o.listing_id = l.id and o.created_at > now() - interval '30 days') offers on true
  where l.status = 'published'
    and (p_topic is null or l.categories @> array[p_topic])
    and not exists (select 1 from public.bans b where b.user_id = l.owner_id)
  order by
    ln(1 + views.n) + 2 * ln(1 + offers.n)
    + 3 * exp(-extract(epoch from now() - l.created_at) / 604800.0)
    + case when exists (select 1 from public.profiles p where p.id = auth.uid() and p.interests && l.categories) then 1 else 0 end
    desc, l.created_at desc
  limit least(greatest(p_limit, 1), 100)
$$;
grant execute on function public.discover_listings(text, integer) to anon, authenticated;

-- Creators: followers, a complete profile and recent activity.
create or replace function public.discover_creators(p_limit integer default 9)
returns table (id uuid, full_name text, avatar_url text, bio text, location text, website text)
language sql stable security definer set search_path = ''
as $$
  select p.id, p.full_name, p.avatar_url, p.bio, p.location, p.website
  from public.profiles p
  where p.discoverable and p.full_name is not null and p.id is distinct from auth.uid()
    and not exists (select 1 from public.bans b where b.user_id = p.id)
  order by
    ln(1 + (select count(*) from public.follows f where f.creator_id = p.id))
    + case when p.avatar_url is not null then 0.5 else 0 end
    + case when p.bio is not null then 0.5 else 0 end
    + case when exists (select 1 from public.listings l where l.owner_id = p.id and l.status = 'published') then 1 else 0 end
    + 2 * exp(-extract(epoch from now() - p.created_at) / 1209600.0)
    desc
  limit least(greatest(p_limit, 1), 50)
$$;
grant execute on function public.discover_creators(integer) to authenticated;

-- ▓▓▓▓▓▓▓▓ 20261013000000_ai_studio.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- AI Studio: every character gets a media library, scripts and AI generations
-- (images, voiceovers, video clips, talking clips, assembled videos).
-- Generation runs on the server (app/api/studio); the database tracks jobs,
-- enforces access, rate limits and a monthly spend limit per person.
-- Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

-- Turns text into a uuid, or null if it isn't one (safe inside storage policies).
create or replace function public.try_uuid(t text)
returns uuid language plpgsql immutable
as $$
begin
  return t::uuid;
exception when others then
  return null;
end;
$$;

-- ── Storage: a private bucket, files at <character id>/<name> ──
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('studio-media', 'studio-media', false, 52428800, array[
  'image/png', 'image/jpeg', 'image/webp', 'image/gif',
  'audio/mpeg', 'audio/mp3', 'audio/wav', 'audio/x-wav', 'audio/wave', 'audio/mp4', 'audio/x-m4a', 'audio/aac', 'audio/ogg', 'audio/webm', 'audio/flac',
  'video/mp4', 'video/webm', 'video/quicktime'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "Studio media: team views" on storage.objects;
create policy "Studio media: team views" on storage.objects for select to authenticated
  using (bucket_id = 'studio-media' and public.can_view_project(public.try_uuid((storage.foldername(name))[1])));
drop policy if exists "Studio media: editors upload" on storage.objects;
create policy "Studio media: editors upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'studio-media' and public.can_edit_project(public.try_uuid((storage.foldername(name))[1])));
drop policy if exists "Studio media: editors replace" on storage.objects;
create policy "Studio media: editors replace" on storage.objects for update to authenticated
  using (bucket_id = 'studio-media' and public.can_edit_project(public.try_uuid((storage.foldername(name))[1])));
drop policy if exists "Studio media: editors remove" on storage.objects;
create policy "Studio media: editors remove" on storage.objects for delete to authenticated
  using (bucket_id = 'studio-media' and public.can_edit_project(public.try_uuid((storage.foldername(name))[1])));

-- ── Generation jobs ──
create table if not exists public.studio_generations (
  id                  uuid primary key default gen_random_uuid(),
  project_id          uuid not null references public.projects (id) on delete cascade,
  created_by          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  tool                text not null check (tool in ('image', 'video', 'voice', 'talking', 'assemble')),
  model               text not null check (char_length(model) <= 120),
  prompt              text check (prompt is null or char_length(prompt) <= 5000),
  params              jsonb not null default '{}'::jsonb,
  inputs              jsonb not null default '[]'::jsonb,
  status              text not null default 'queued' check (status in ('queued', 'running', 'succeeded', 'failed', 'canceled')),
  provider            text not null default 'fal',
  provider_request_id text,
  provider_meta       jsonb not null default '{}'::jsonb,   -- status/result URLs from the provider
  error               text check (error is null or char_length(error) <= 1000),
  cost_cents          integer not null default 0 check (cost_cents >= 0),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  finished_at         timestamptz
);
alter table public.studio_generations add column if not exists provider_meta jsonb not null default '{}'::jsonb;
create index if not exists studio_generations_project_idx on public.studio_generations (project_id, created_at desc);
create index if not exists studio_generations_user_month_idx on public.studio_generations (created_by, created_at);
alter table public.studio_generations enable row level security;
drop policy if exists "Generations: team views" on public.studio_generations;
create policy "Generations: team views" on public.studio_generations for select to authenticated
  using (public.can_view_project(project_id));
drop policy if exists "Generations: staff read" on public.studio_generations;
create policy "Generations: staff read" on public.studio_generations for select to authenticated using (public.is_staff());
-- All writes go through the functions below.
revoke insert, update, delete on public.studio_generations from anon, authenticated;

-- ── Media library ──
create table if not exists public.studio_media (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null references public.projects (id) on delete cascade,
  added_by      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  kind          text not null check (kind in ('image', 'audio', 'video')),
  source        text not null default 'upload' check (source in ('upload', 'generated')),
  label         text check (label is null or char_length(label) <= 120),
  path          text not null check (char_length(path) <= 300),
  mime          text check (mime is null or char_length(mime) <= 80),
  bytes         bigint check (bytes is null or bytes >= 0),
  duration_ms   integer check (duration_ms is null or duration_ms >= 0),
  generation_id uuid references public.studio_generations (id) on delete set null,
  created_at    timestamptz not null default now(),
  unique (path)
);
create index if not exists studio_media_project_idx on public.studio_media (project_id, created_at desc);
alter table public.studio_media enable row level security;
drop policy if exists "Media: team views" on public.studio_media;
create policy "Media: team views" on public.studio_media for select to authenticated using (public.can_view_project(project_id));
drop policy if exists "Media: editors upload" on public.studio_media;
create policy "Media: editors upload" on public.studio_media for insert to authenticated
  with check (added_by = (select auth.uid()) and source = 'upload' and generation_id is null
              and public.can_edit_project(project_id) and path like project_id::text || '/%');
drop policy if exists "Media: editors remove" on public.studio_media;
create policy "Media: editors remove" on public.studio_media for delete to authenticated using (public.can_edit_project(project_id));
drop policy if exists "Media: editors rename" on public.studio_media;
create policy "Media: editors rename" on public.studio_media for update to authenticated
  using (public.can_edit_project(project_id)) with check (public.can_edit_project(project_id));
revoke update on public.studio_media from authenticated;
grant update (label, duration_ms) on public.studio_media to authenticated;

-- ── Scripts: a title and a list of scenes ──
-- Each scene: { id, shot, line, voice, clip_media, voice_media }
create table if not exists public.studio_scripts (
  id          uuid primary key default gen_random_uuid(),
  project_id  uuid not null references public.projects (id) on delete cascade,
  created_by  uuid not null default auth.uid() references auth.users (id) on delete cascade,
  title       text not null default 'Untitled script' check (char_length(title) between 1 and 120),
  scenes      jsonb not null default '[]'::jsonb
                check (jsonb_typeof(scenes) = 'array' and jsonb_array_length(scenes) <= 60 and pg_column_size(scenes) < 200000),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists studio_scripts_project_idx on public.studio_scripts (project_id, updated_at desc);
alter table public.studio_scripts enable row level security;
drop policy if exists "Scripts: team views" on public.studio_scripts;
create policy "Scripts: team views" on public.studio_scripts for select to authenticated using (public.can_view_project(project_id));
drop policy if exists "Scripts: editors add" on public.studio_scripts;
create policy "Scripts: editors add" on public.studio_scripts for insert to authenticated
  with check (created_by = (select auth.uid()) and public.can_edit_project(project_id));
drop policy if exists "Scripts: editors edit" on public.studio_scripts;
create policy "Scripts: editors edit" on public.studio_scripts for update to authenticated
  using (public.can_edit_project(project_id)) with check (public.can_edit_project(project_id));
drop policy if exists "Scripts: editors remove" on public.studio_scripts;
create policy "Scripts: editors remove" on public.studio_scripts for delete to authenticated using (public.can_edit_project(project_id));

create or replace function public.touch_updated_at()
returns trigger language plpgsql
as $$ begin new.updated_at := now(); return new; end; $$;
drop trigger if exists touch_updated_at on public.studio_scripts;
create trigger touch_updated_at before update on public.studio_scripts for each row execute procedure public.touch_updated_at();
drop trigger if exists touch_updated_at on public.studio_generations;
create trigger touch_updated_at before update on public.studio_generations for each row execute procedure public.touch_updated_at();

-- Rate limits and bans (see the safety migration).
drop trigger if exists rate_limit on public.studio_generations;
create trigger rate_limit before insert on public.studio_generations
  for each row execute procedure public.rate_limit('created_by', '1 hour', '60');
drop trigger if exists member_can_create on public.studio_generations;
create trigger member_can_create before insert on public.studio_generations
  for each row execute procedure public.member_can_create('verified');
drop trigger if exists rate_limit on public.studio_media;
create trigger rate_limit before insert on public.studio_media
  for each row execute procedure public.rate_limit('added_by', '1 hour', '300');
drop trigger if exists member_can_create on public.studio_media;
create trigger member_can_create before insert on public.studio_media
  for each row execute procedure public.member_can_create();

-- ── Monthly spend limit (in cents of provider cost) ──
create table if not exists public.studio_limits (
  user_id       uuid primary key references auth.users (id) on delete cascade,
  monthly_cents integer not null check (monthly_cents >= 0),
  updated_at    timestamptz not null default now()
);
alter table public.studio_limits enable row level security;
drop policy if exists "Studio limits: own or staff" on public.studio_limits;
create policy "Studio limits: own or staff" on public.studio_limits for select to authenticated
  using (user_id = (select auth.uid()) or public.is_staff());
revoke insert, update, delete on public.studio_limits from anon, authenticated;

-- Default allowance for everyone: $10 of generation a month. Change the number here.
create or replace function public.studio_default_monthly_cents()
returns integer language sql immutable as $$ select 1000 $$;

create or replace function public.studio_usage(uid uuid default auth.uid())
returns table (used_cents integer, limit_cents integer)
language sql stable security definer set search_path = ''
as $$
  select
    coalesce((select sum(g.cost_cents)::integer from public.studio_generations g
              where g.created_by = uid and g.created_at >= date_trunc('month', now())
                and not (g.status in ('failed', 'canceled') and g.provider_request_id is null)), 0),
    coalesce((select l.monthly_cents from public.studio_limits l where l.user_id = uid), public.studio_default_monthly_cents())
  where uid = auth.uid() or public.is_staff()
$$;
grant execute on function public.studio_usage(uuid) to authenticated;

-- ── Starting, tracking and finishing a generation ──
create or replace function public.studio_start_generation(
  p_project uuid, p_tool text, p_model text, p_prompt text, p_params jsonb, p_inputs jsonb, p_cost_cents integer)
returns uuid language plpgsql security definer set search_path = ''
as $$
declare used integer; cap integer; new_id uuid;
begin
  if auth.uid() is null then raise exception 'Log in first.'; end if;
  if not public.can_edit_project(p_project) then raise exception 'You can only generate for characters you can edit.'; end if;
  if coalesce(p_cost_cents, 0) < 0 then raise exception 'Invalid cost.'; end if;
  select u.used_cents, u.limit_cents into used, cap from public.studio_usage(auth.uid()) u;
  if used + coalesce(p_cost_cents, 0) > cap then
    raise exception 'This would go over your monthly AI Studio limit ($% of $% used). Ask the tsayvish team to raise it.',
      to_char(used / 100.0, 'FM999990.00'), to_char(cap / 100.0, 'FM999990.00')
      using hint = 'over_limit';
  end if;
  insert into public.studio_generations (project_id, created_by, tool, model, prompt, params, inputs, cost_cents)
  values (p_project, auth.uid(), p_tool, p_model, nullif(trim(p_prompt), ''), coalesce(p_params, '{}'::jsonb), coalesce(p_inputs, '[]'::jsonb), coalesce(p_cost_cents, 0))
  returning id into new_id;
  return new_id;
end;
$$;

drop function if exists public.studio_mark_submitted(uuid, text);
create or replace function public.studio_mark_submitted(p_id uuid, p_request_id text, p_meta jsonb default '{}'::jsonb)
returns void language plpgsql security definer set search_path = ''
as $$
begin
  if pg_column_size(p_meta) > 4000 then raise exception 'Too much detail.'; end if;
  update public.studio_generations set status = 'running', provider_request_id = left(p_request_id, 200), provider_meta = coalesce(p_meta, '{}'::jsonb)
  where id = p_id and created_by = auth.uid() and status = 'queued' and provider_request_id is null;
  if not found then raise exception 'Generation not found.'; end if;
end;
$$;

-- Marks a job failed or canceled. Anyone who can edit the character may cancel.
create or replace function public.studio_end_generation(p_id uuid, p_status text, p_error text default null)
returns void language plpgsql security definer set search_path = ''
as $$
declare g public.studio_generations;
begin
  if p_status not in ('failed', 'canceled') then raise exception 'Invalid status.'; end if;
  select * into g from public.studio_generations where id = p_id;
  if g.id is null or not public.can_edit_project(g.project_id) then raise exception 'Generation not found.'; end if;
  update public.studio_generations set status = p_status, error = left(p_error, 1000), finished_at = now()
  where id = p_id and status in ('queued', 'running');
end;
$$;

-- Records the finished files (already uploaded to studio-media) and, if the job came
-- from a script scene, links the result into that scene. Runs once per job.
-- p_outputs: [{ "path", "kind", "mime", "bytes", "duration_ms" }]
create or replace function public.studio_complete_generation(p_id uuid, p_outputs jsonb)
returns setof public.studio_media language plpgsql security definer set search_path = ''
as $$
declare g public.studio_generations; o jsonb; m public.studio_media; first_media uuid; role text; sid text; scr uuid;
begin
  select * into g from public.studio_generations where id = p_id for update;
  if g.id is null or not public.can_edit_project(g.project_id) then raise exception 'Generation not found.'; end if;
  if g.status not in ('queued', 'running') then
    return query select * from public.studio_media where generation_id = p_id order by created_at;
    return;
  end if;
  if jsonb_typeof(p_outputs) <> 'array' or jsonb_array_length(p_outputs) = 0 or jsonb_array_length(p_outputs) > 8 then
    raise exception 'No output files.';
  end if;
  for o in select * from jsonb_array_elements(p_outputs) loop
    if (o->>'path') not like g.project_id::text || '/%' then raise exception 'Output must be stored with the character.'; end if;
    insert into public.studio_media (project_id, added_by, kind, source, label, path, mime, bytes, duration_ms, generation_id)
    values (g.project_id, g.created_by, o->>'kind', 'generated', left(coalesce(g.params->>'label', g.prompt, g.tool), 120),
            o->>'path', o->>'mime', nullif(o->>'bytes', '')::bigint, nullif(o->>'duration_ms', '')::integer, g.id)
    on conflict (path) do update set generation_id = excluded.generation_id
    returning * into m;
    first_media := coalesce(first_media, m.id);
    return next m;
  end loop;
  update public.studio_generations set status = 'succeeded', error = null, finished_at = now() where id = p_id;

  role := g.params->>'scene_role';
  sid := g.params->>'scene_id';
  scr := public.try_uuid(g.params->>'script_id');
  if role in ('clip', 'voice') and sid is not null and scr is not null then
    update public.studio_scripts s
       set scenes = (select coalesce(jsonb_agg(case when e->>'id' = sid then e || jsonb_build_object(role || '_media', first_media::text) else e end order by ord), '[]'::jsonb)
                       from jsonb_array_elements(s.scenes) with ordinality t(e, ord))
     where s.id = scr and s.project_id = g.project_id;
  end if;
end;
$$;

grant execute on function public.studio_start_generation(uuid, text, text, text, jsonb, jsonb, integer) to authenticated;
grant execute on function public.studio_mark_submitted(uuid, text, jsonb) to authenticated;
grant execute on function public.studio_end_generation(uuid, text, text) to authenticated;
grant execute on function public.studio_complete_generation(uuid, jsonb) to authenticated;

-- ── Staff can change someone's monthly allowance ──
create or replace function public.admin_set_studio_limit(p_user uuid, p_cents integer)
returns void language plpgsql security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  if p_cents is null or p_cents < 0 then raise exception 'Enter an amount of $0 or more.'; end if;
  insert into public.studio_limits (user_id, monthly_cents) values (p_user, p_cents)
  on conflict (user_id) do update set monthly_cents = excluded.monthly_cents, updated_at = now();
  perform public.log_admin_action('studio_limit', 'user', p_user::text, jsonb_build_object('monthly_cents', p_cents));
end;
$$;
grant execute on function public.admin_set_studio_limit(uuid, integer) to authenticated;

-- ▓▓▓▓▓▓▓▓ 20261014000000_credits.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Credits: people pay for AI Studio generation upfront.
-- Balances are in US cents. Each job is charged when it starts (provider cost × markup)
-- and refunded automatically if it fails. Purchases come from Stripe Checkout and are
-- recorded by the server with a shared secret (see new_billing_secret below).
-- Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

-- ── Settings: change the numbers here ──
-- What people pay per cent of provider cost.
create or replace function public.credit_markup()
returns numeric language sql immutable as $$ select 1.5::numeric $$;
-- Free credits every account gets once, in cents.
create or replace function public.starter_credits_cents()
returns integer language sql immutable as $$ select 100 $$;
grant execute on function public.credit_markup() to anon, authenticated;
grant execute on function public.starter_credits_cents() to anon, authenticated;

-- ── The ledger: every purchase, charge and refund ──
create table if not exists public.credit_ledger (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users (id) on delete cascade,
  kind           text not null check (kind in ('starter', 'purchase', 'grant', 'charge', 'refund', 'adjust')),
  amount_cents   integer not null check (amount_cents <> 0 and abs(amount_cents) <= 10000000),
  generation_id  uuid references public.studio_generations (id) on delete set null,
  stripe_session text unique,
  note           text check (note is null or char_length(note) <= 300),
  created_by     uuid default auth.uid() references auth.users (id) on delete set null,
  created_at     timestamptz not null default now()
);
create index if not exists credit_ledger_user_idx on public.credit_ledger (user_id, created_at desc);
create unique index if not exists credit_ledger_one_starter on public.credit_ledger (user_id) where kind = 'starter';
create unique index if not exists credit_ledger_one_per_job on public.credit_ledger (generation_id, kind) where generation_id is not null;
alter table public.credit_ledger enable row level security;
drop policy if exists "Credits: own or staff" on public.credit_ledger;
create policy "Credits: own or staff" on public.credit_ledger for select to authenticated
  using (user_id = (select auth.uid()) or public.is_staff());
revoke insert, update, delete on public.credit_ledger from anon, authenticated;

alter table public.studio_generations add column if not exists price_cents integer not null default 0 check (price_cents >= 0);

create or replace function public.credit_balance(uid uuid default auth.uid())
returns integer language sql stable security definer set search_path = ''
as $$
  select coalesce(sum(amount_cents), 0)::integer from public.credit_ledger
  where user_id = uid and (uid = auth.uid() or public.is_staff())
$$;
grant execute on function public.credit_balance(uuid) to authenticated;

-- What a job will cost the person, in cents.
create or replace function public.credit_price(p_cost_cents integer)
returns integer language sql immutable
as $$ select greatest(1, ceil(greatest(p_cost_cents, 0) * public.credit_markup()))::integer $$;
grant execute on function public.credit_price(integer) to anon, authenticated;

-- Gives the one-time starter credits. Safe to call any number of times. Returns the balance.
create or replace function public.claim_starter_credits()
returns integer language plpgsql security definer set search_path = ''
as $$
begin
  if auth.uid() is null then return 0; end if;
  if public.starter_credits_cents() > 0 and not public.is_banned(auth.uid()) then
    insert into public.credit_ledger (user_id, kind, amount_cents, note, created_by)
    values (auth.uid(), 'starter', public.starter_credits_cents(), 'Welcome credits', auth.uid())
    on conflict do nothing;
  end if;
  return public.credit_balance(auth.uid());
end;
$$;
grant execute on function public.claim_starter_credits() to authenticated;

-- ── Purchases: recorded by the server after Stripe confirms payment ──
-- The server proves itself with a secret whose hash lives here. Make one with:
--   select public.new_billing_secret();
-- and put the result in Vercel as BILLING_DB_SECRET. Running it again replaces the old one.
create table if not exists public.billing_secret (
  id         boolean primary key default true check (id),
  hash       text not null,
  created_at timestamptz not null default now()
);
alter table public.billing_secret enable row level security;
revoke all on public.billing_secret from anon, authenticated;

create or replace function public.new_billing_secret()
returns text language plpgsql security definer set search_path = ''
as $$
declare s text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
begin
  insert into public.billing_secret (id, hash) values (true, encode(sha256(convert_to(s, 'UTF8')), 'hex'))
  on conflict (id) do update set hash = excluded.hash, created_at = now();
  return s;
end;
$$;
revoke all on function public.new_billing_secret() from public, anon, authenticated;

-- Adds purchased credits once per Stripe Checkout session. Returns true if this call added them.
create or replace function public.record_credit_purchase(p_secret text, p_session text, p_user uuid, p_cents integer, p_note text default null)
returns boolean language plpgsql security definer set search_path = ''
as $$
declare ok boolean; n integer;
begin
  select hash = encode(sha256(convert_to(coalesce(p_secret, ''), 'UTF8')), 'hex') into ok from public.billing_secret where id;
  if not coalesce(ok, false) then raise exception 'Not allowed.'; end if;
  if p_session is null or p_user is null or p_cents is null or p_cents <= 0 then raise exception 'Invalid purchase.'; end if;
  if not exists (select 1 from auth.users where id = p_user) then raise exception 'Unknown member.'; end if;
  insert into public.credit_ledger (user_id, kind, amount_cents, stripe_session, note, created_by)
  values (p_user, 'purchase', p_cents, left(p_session, 255), left(coalesce(p_note, 'Credits'), 300), null)
  on conflict (stripe_session) do nothing;
  get diagnostics n = row_count;
  if n > 0 then
    insert into public.notifications (user_id, type, actor_id, body)
    values (p_user, 'credits_added', null, format('$%s of AI Studio credits added.', to_char(p_cents / 100.0, 'FM999990.00')));
  end if;
  return n > 0;
end;
$$;
revoke all on function public.record_credit_purchase(text, text, uuid, integer, text) from public;
grant execute on function public.record_credit_purchase(text, text, uuid, integer, text) to anon, authenticated;

-- A notification type for purchases.
alter table public.notifications drop constraint if exists notifications_type_check;
alter table public.notifications add constraint notifications_type_check check (type in (
  'offer_received', 'offer_accepted', 'offer_declined', 'offer_withdrawn', 'offer_paid', 'new_follower',
  'service_update', 'service_active', 'partnership_update', 'agreement_proposed', 'agreement_signed', 'credits_added'));

-- ── Staff: add or remove credits, with a note ──
create or replace function public.admin_adjust_credits(p_user uuid, p_cents integer, p_note text)
returns integer language plpgsql security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  if p_cents is null or p_cents = 0 then raise exception 'Enter an amount.'; end if;
  if coalesce(trim(p_note), '') = '' then raise exception 'Add a short note saying why.'; end if;
  insert into public.credit_ledger (user_id, kind, amount_cents, note, created_by)
  values (p_user, case when p_cents > 0 then 'grant' else 'adjust' end, p_cents, left(trim(p_note), 300), auth.uid());
  perform public.log_admin_action('credits', 'user', p_user::text, jsonb_build_object('cents', p_cents, 'note', p_note));
  return public.credit_balance(p_user);
end;
$$;
grant execute on function public.admin_adjust_credits(uuid, integer, text) to authenticated;

-- Money in and out this month, for the admin billing page.
create or replace function public.billing_summary()
returns table (purchased_cents bigint, spent_cents bigint, provider_cents bigint, outstanding_cents bigint, buyers bigint)
language plpgsql stable security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  return query select
    coalesce((select sum(amount_cents) from public.credit_ledger where kind = 'purchase' and created_at >= date_trunc('month', now())), 0)::bigint,
    coalesce((select -sum(amount_cents) from public.credit_ledger where kind in ('charge', 'refund') and created_at >= date_trunc('month', now())), 0)::bigint,
    coalesce((select sum(cost_cents) from public.studio_generations
              where created_at >= date_trunc('month', now()) and not (status in ('failed', 'canceled') and provider_request_id is null)), 0)::bigint,
    coalesce((select sum(amount_cents) from public.credit_ledger), 0)::bigint,
    (select count(distinct user_id) from public.credit_ledger where kind = 'purchase' and created_at >= date_trunc('month', now()))::bigint;
end;
$$;
grant execute on function public.billing_summary() to authenticated;

-- ── Generation now charges credits ──
-- A staff-set monthly cap (studio_limits) still applies if one exists for the person.
create or replace function public.studio_start_generation(
  p_project uuid, p_tool text, p_model text, p_prompt text, p_params jsonb, p_inputs jsonb, p_cost_cents integer)
returns uuid language plpgsql security definer set search_path = ''
as $$
declare used integer; cap integer; new_id uuid; price integer; bal integer;
begin
  if auth.uid() is null then raise exception 'Log in first.'; end if;
  if not public.can_edit_project(p_project) then raise exception 'You can only generate for characters you can edit.'; end if;
  if coalesce(p_cost_cents, 0) < 0 then raise exception 'Invalid cost.'; end if;

  -- One job at a time per person while the balance is checked.
  perform pg_advisory_xact_lock(hashtext('credits:' || auth.uid()::text));

  select l.monthly_cents into cap from public.studio_limits l where l.user_id = auth.uid();
  if cap is not null then
    select u.used_cents into used from public.studio_usage(auth.uid()) u;
    if used + coalesce(p_cost_cents, 0) > cap then
      raise exception 'You’ve reached the monthly AI Studio limit on your account. Contact the tsayvish team.' using hint = 'over_limit';
    end if;
  end if;

  price := public.credit_price(coalesce(p_cost_cents, 0));
  bal := public.credit_balance(auth.uid());
  if bal < price then
    raise exception 'Not enough credits: this costs $% and you have $%. Top up to keep going.',
      to_char(price / 100.0, 'FM999990.00'), to_char(bal / 100.0, 'FM999990.00')
      using hint = 'no_credits';
  end if;

  insert into public.studio_generations (project_id, created_by, tool, model, prompt, params, inputs, cost_cents, price_cents)
  values (p_project, auth.uid(), p_tool, p_model, nullif(trim(p_prompt), ''), coalesce(p_params, '{}'::jsonb), coalesce(p_inputs, '[]'::jsonb), coalesce(p_cost_cents, 0), price)
  returning id into new_id;
  insert into public.credit_ledger (user_id, kind, amount_cents, generation_id, note, created_by)
  values (auth.uid(), 'charge', -price, new_id, left(coalesce(p_params->>'label', p_prompt, p_tool), 300), auth.uid());
  return new_id;
end;
$$;

-- Failed jobs are refunded. Stopped jobs are refunded only if they never reached the provider.
create or replace function public.studio_end_generation(p_id uuid, p_status text, p_error text default null)
returns void language plpgsql security definer set search_path = ''
as $$
declare g public.studio_generations;
begin
  if p_status not in ('failed', 'canceled') then raise exception 'Invalid status.'; end if;
  select * into g from public.studio_generations where id = p_id for update;
  if g.id is null or not public.can_edit_project(g.project_id) then raise exception 'Generation not found.'; end if;
  if g.status not in ('queued', 'running') then return; end if;
  update public.studio_generations set status = p_status, error = left(p_error, 1000), finished_at = now() where id = p_id;
  if g.price_cents > 0 and (p_status = 'failed' or g.provider_request_id is null) then
    insert into public.credit_ledger (user_id, kind, amount_cents, generation_id, note, created_by)
    values (g.created_by, 'refund', g.price_cents, g.id, case when p_status = 'failed' then 'Refund: didn’t finish' else 'Refund: stopped before it started' end, auth.uid())
    on conflict do nothing;
  end if;
end;
$$;

grant execute on function public.studio_start_generation(uuid, text, text, text, jsonb, jsonb, integer) to authenticated;
grant execute on function public.studio_end_generation(uuid, text, text) to authenticated;

-- ▓▓▓▓▓▓▓▓ 20261015000000_billing_exempt.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Billing off for chosen members: their AI Studio jobs don't use credits.
-- The provider cost is still recorded (Admin → Billing), and any staff-set
-- monthly spend cap still applies. Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════

create table if not exists public.billing_exempt (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  note       text check (note is null or char_length(note) <= 300),
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.billing_exempt enable row level security;
drop policy if exists "Billing exempt: own or staff" on public.billing_exempt;
create policy "Billing exempt: own or staff" on public.billing_exempt for select to authenticated
  using (user_id = (select auth.uid()) or public.is_staff());
revoke insert, update, delete on public.billing_exempt from anon, authenticated;

create or replace function public.is_billing_exempt(uid uuid default auth.uid())
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.billing_exempt where user_id = uid) and (uid = auth.uid() or public.is_staff()) $$;
grant execute on function public.is_billing_exempt(uuid) to authenticated;

create or replace function public.admin_set_billing_exempt(p_user uuid, p_exempt boolean, p_note text default null)
returns void language plpgsql security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  if p_exempt then
    insert into public.billing_exempt (user_id, note, created_by) values (p_user, nullif(left(trim(coalesce(p_note, '')), 300), ''), auth.uid())
    on conflict (user_id) do update set note = excluded.note, created_by = excluded.created_by, created_at = now();
  else
    delete from public.billing_exempt where user_id = p_user;
  end if;
  perform public.log_admin_action(case when p_exempt then 'billing_off' else 'billing_on' end, 'user', p_user::text, jsonb_build_object('note', p_note));
end;
$$;
grant execute on function public.admin_set_billing_exempt(uuid, boolean, text) to authenticated;

-- Generation: free for exempt members, otherwise charged as before.
create or replace function public.studio_start_generation(
  p_project uuid, p_tool text, p_model text, p_prompt text, p_params jsonb, p_inputs jsonb, p_cost_cents integer)
returns uuid language plpgsql security definer set search_path = ''
as $$
declare used integer; cap integer; new_id uuid; price integer; bal integer; free boolean;
begin
  if auth.uid() is null then raise exception 'Log in first.'; end if;
  if not public.can_edit_project(p_project) then raise exception 'You can only generate for characters you can edit.'; end if;
  if coalesce(p_cost_cents, 0) < 0 then raise exception 'Invalid cost.'; end if;

  perform pg_advisory_xact_lock(hashtext('credits:' || auth.uid()::text));

  select l.monthly_cents into cap from public.studio_limits l where l.user_id = auth.uid();
  if cap is not null then
    select u.used_cents into used from public.studio_usage(auth.uid()) u;
    if used + coalesce(p_cost_cents, 0) > cap then
      raise exception 'You’ve reached the monthly AI Studio limit on your account. Contact the tsayvish team.' using hint = 'over_limit';
    end if;
  end if;

  free := exists (select 1 from public.billing_exempt where user_id = auth.uid());
  price := case when free then 0 else public.credit_price(coalesce(p_cost_cents, 0)) end;
  if not free then
    bal := public.credit_balance(auth.uid());
    if bal < price then
      raise exception 'Not enough credits: this costs $% and you have $%. Top up to keep going.',
        to_char(price / 100.0, 'FM999990.00'), to_char(bal / 100.0, 'FM999990.00')
        using hint = 'no_credits';
    end if;
  end if;

  insert into public.studio_generations (project_id, created_by, tool, model, prompt, params, inputs, cost_cents, price_cents)
  values (p_project, auth.uid(), p_tool, p_model, nullif(trim(p_prompt), ''), coalesce(p_params, '{}'::jsonb), coalesce(p_inputs, '[]'::jsonb), coalesce(p_cost_cents, 0), price)
  returning id into new_id;
  if price > 0 then
    insert into public.credit_ledger (user_id, kind, amount_cents, generation_id, note, created_by)
    values (auth.uid(), 'charge', -price, new_id, left(coalesce(p_params->>'label', p_prompt, p_tool), 300), auth.uid());
  end if;
  return new_id;
end;
$$;
grant execute on function public.studio_start_generation(uuid, text, text, text, jsonb, jsonb, integer) to authenticated;

-- ▓▓▓▓▓▓▓▓ 20261016000000_admin_members.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Admin → Members: remove a member's monthly AI Studio spend cap. Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════
create or replace function public.admin_clear_studio_limit(p_user uuid)
returns void language plpgsql security definer set search_path = ''
as $$
begin
  perform public.require_staff();
  delete from public.studio_limits where user_id = p_user;
  perform public.log_admin_action('studio_limit_removed', 'user', p_user::text, '{}'::jsonb);
end;
$$;
grant execute on function public.admin_clear_studio_limit(uuid) to authenticated;

-- ▓▓▓▓▓▓▓▓ 20261017000000_delete_content.sql ▓▓▓▓▓▓▓▓

-- ═════════════════════════════════════════════════════════════════════════
-- Deleting AI Studio results. Removes a finished (or failed) job and the files it
-- made from the library; returns their storage paths so the app can delete the files.
-- Credit history keeps its rows. Safe to run again.
-- ═════════════════════════════════════════════════════════════════════════
create or replace function public.studio_delete_generation(p_id uuid)
returns setof text language plpgsql security definer set search_path = ''
as $$
declare g public.studio_generations;
begin
  select * into g from public.studio_generations where id = p_id;
  if g.id is null or not public.can_edit_project(g.project_id) then raise exception 'Not found.'; end if;
  if g.status in ('queued', 'running') then raise exception 'Stop it first, then delete it.'; end if;
  return query delete from public.studio_media where generation_id = p_id returning path;
  delete from public.studio_generations where id = p_id;
end;
$$;
grant execute on function public.studio_delete_generation(uuid) to authenticated;
